export const CHEMICAL_COORDINATION_INTEGRATION = [
  // ---- MCQ ----
  { id: 'cc-1', type: 'mcq', question: 'Chemical coordination in the body, in addition to neural control, is achieved primarily through:', options: ['Bones', 'Hormones secreted by endocrine glands', 'Muscles alone', 'Blood cells'], correctIndex: 1, explanation: 'Hormones, secreted by endocrine glands into the blood, mediate chemical coordination throughout the body.', difficulty: 'easy' },
  { id: 'cc-2', type: 'mcq', question: 'Endocrine glands are also known as ductless glands because they:', options: ['Have no cells at all', 'Secrete hormones directly into the blood, without a duct', 'Only secrete digestive enzymes', 'Are located only in the brain'], correctIndex: 1, explanation: 'Endocrine glands lack ducts and release their secretions (hormones) directly into the bloodstream.', difficulty: 'easy' },
  { id: 'cc-3', type: 'mcq', question: 'The gland often called the "master gland" because it regulates the activity of several other endocrine glands is the:', options: ['Thyroid gland', 'Pituitary gland', 'Adrenal gland', 'Pancreas'], correctIndex: 1, explanation: 'The pituitary gland regulates many other endocrine glands, earning the "master gland" title.', difficulty: 'easy' },
  { id: 'cc-4', type: 'mcq', question: 'The pituitary gland is functionally and anatomically closely linked to, and regulated by, the:', options: ['Cerebellum', 'Hypothalamus', 'Thyroid gland', 'Adrenal medulla'], correctIndex: 1, explanation: 'The hypothalamus closely regulates pituitary function through releasing and inhibiting hormones.', difficulty: 'medium' },
  { id: 'cc-5', type: 'mcq', question: 'The pituitary gland is anatomically divided into which two main lobes?', options: ['Left and right lobes', 'Anterior (adenohypophysis) and posterior (neurohypophysis) lobes', 'Superior and inferior lobes', 'Cortex and medulla'], correctIndex: 1, explanation: 'The pituitary consists of an anterior lobe (adenohypophysis) and a posterior lobe (neurohypophysis).', difficulty: 'medium' },
  { id: 'cc-6', type: 'mcq', question: 'Growth Hormone (GH), which stimulates overall body growth, is secreted by the:', options: ['Posterior pituitary', 'Anterior pituitary', 'Thyroid gland', 'Adrenal cortex'], correctIndex: 1, explanation: 'GH is one of several hormones secreted by the anterior pituitary (adenohypophysis).', difficulty: 'medium' },
  { id: 'cc-7', type: 'mcq', question: 'Thyroid Stimulating Hormone (TSH), which regulates thyroid gland activity, is secreted by the:', options: ['Anterior pituitary', 'Posterior pituitary', 'Thyroid gland itself', 'Parathyroid gland'], correctIndex: 0, explanation: 'TSH, secreted by the anterior pituitary, stimulates the thyroid gland to produce thyroid hormones.', difficulty: 'medium' },
  { id: 'cc-8', type: 'mcq', question: 'Adrenocorticotropic Hormone (ACTH), which stimulates the adrenal cortex, is secreted by the:', options: ['Posterior pituitary', 'Anterior pituitary', 'Adrenal medulla', 'Pancreas'], correctIndex: 1, explanation: 'ACTH from the anterior pituitary stimulates the adrenal cortex to secrete corticosteroids.', difficulty: 'medium' },
  { id: 'cc-9', type: 'mcq', question: 'Prolactin, which stimulates milk production/secretion in mammary glands, is secreted by the:', options: ['Posterior pituitary', 'Anterior pituitary', 'Ovary', 'Thyroid'], correctIndex: 1, explanation: 'Prolactin is secreted by the anterior pituitary and stimulates lactation.', difficulty: 'medium' },
  { id: 'cc-10', type: 'mcq', question: 'Luteinizing Hormone (LH) and Follicle Stimulating Hormone (FSH), regulating gonadal function, are secreted by the:', options: ['Posterior pituitary', 'Anterior pituitary', 'Adrenal medulla', 'Pineal gland'], correctIndex: 1, explanation: 'LH and FSH, gonadotropins, are secreted by the anterior pituitary to regulate testes/ovary function.', difficulty: 'medium' },
  { id: 'cc-11', type: 'mcq', question: 'Oxytocin, which stimulates uterine contractions during childbirth and milk ejection, is released from the:', options: ['Anterior pituitary', 'Posterior pituitary', 'Adrenal cortex', 'Parathyroid'], correctIndex: 1, explanation: 'Oxytocin is synthesised in the hypothalamus and released from the posterior pituitary.', difficulty: 'medium' },
  { id: 'cc-12', type: 'mcq', question: 'Antidiuretic Hormone (ADH/vasopressin), which promotes water reabsorption in the kidney, is released from the:', options: ['Anterior pituitary', 'Posterior pituitary', 'Adrenal medulla', 'Thymus'], correctIndex: 1, explanation: 'ADH, like oxytocin, is synthesised in the hypothalamus but released from the posterior pituitary.', difficulty: 'medium' },
  { id: 'cc-13', type: 'mcq', question: 'The pineal gland, located in the brain, primarily secretes the hormone:', options: ['Melatonin', 'Thyroxine', 'Insulin', 'Cortisol'], correctIndex: 0, explanation: 'The pineal gland secretes melatonin, involved in regulating circadian (day-night) rhythms.', difficulty: 'medium' },
  { id: 'cc-14', type: 'mcq', question: 'Melatonin secretion is closely linked to regulating the body\'s:', options: ['Blood glucose levels', 'Circadian rhythm (sleep-wake cycle)', 'Bone density', 'Blood clotting'], correctIndex: 1, explanation: 'Melatonin plays a key role in regulating circadian rhythms and sleep patterns.', difficulty: 'medium' },
  { id: 'cc-15', type: 'mcq', question: "The thyroid gland's main hormones, T3 (triiodothyronine) and T4 (thyroxine), primarily regulate:", options: ['Blood clotting only', 'The basal metabolic rate of the body', 'Muscle contraction directly', 'Digestive enzyme secretion'], correctIndex: 1, explanation: 'Thyroid hormones (T3/T4) regulate the overall basal metabolic rate.', difficulty: 'medium' },
  { id: 'cc-16', type: 'mcq', question: 'The synthesis of thyroid hormones requires an adequate supply of:', options: ['Calcium', 'Iodine', 'Sodium', 'Iron'], correctIndex: 1, explanation: 'Iodine is an essential component required for thyroid hormone (T3/T4) synthesis.', difficulty: 'medium' },
  { id: 'cc-17', type: 'mcq', question: 'Calcitonin, which helps lower blood calcium levels, is secreted by the:', options: ['Parathyroid gland', 'Thyroid gland', 'Adrenal cortex', 'Pancreas'], correctIndex: 1, explanation: 'Calcitonin, secreted by the thyroid, helps reduce elevated blood calcium levels.', difficulty: 'medium' },
  { id: 'cc-18', type: 'mcq', question: 'Parathyroid Hormone (PTH), which increases blood calcium levels, is secreted by the:', options: ['Thyroid gland', 'Parathyroid glands', 'Adrenal medulla', 'Thymus'], correctIndex: 1, explanation: 'PTH, from the parathyroid glands, raises blood calcium levels — largely opposing calcitonin\'s effect.', difficulty: 'medium' },
  { id: 'cc-19', type: 'mcq', question: 'The thymus gland, important for immune system development, secretes hormones called:', options: ['Thymosins', 'Thyroxines', 'Insulins', 'Androgens'], correctIndex: 0, explanation: 'Thymosins, secreted by the thymus, play a role in the maturation of T-lymphocytes.', difficulty: 'medium' },
  { id: 'cc-20', type: 'mcq', question: 'The thymus gland tends to show significant involution (shrinkage) as a person progresses through:', options: ['Early childhood', 'Old age', 'Only during pregnancy', 'It never changes size at any life stage'], correctIndex: 1, explanation: 'The thymus is relatively large in children and progressively shrinks/involutes with advancing age.', difficulty: 'medium' },
  { id: 'cc-21', type: 'mcq', question: 'The adrenal gland is structurally divided into an outer region and an inner region called the:', options: ['Adrenal cortex and adrenal medulla respectively', 'Adrenal medulla and adrenal cortex respectively', 'Only the adrenal cortex, with no inner region', 'Only the adrenal medulla, with no outer region'], correctIndex: 0, explanation: 'The adrenal gland has an outer cortex and an inner medulla, each secreting different hormones.', difficulty: 'medium' },
  { id: 'cc-22', type: 'mcq', question: 'The adrenal cortex secretes steroid hormones broadly classified as:', options: ['Only androgens', 'Glucocorticoids, mineralocorticoids, and androgens', 'Only thyroid hormones', 'Only insulin and glucagon'], correctIndex: 1, explanation: 'The adrenal cortex secretes three classes: glucocorticoids, mineralocorticoids, and androgens.', difficulty: 'medium' },
  { id: 'cc-23', type: 'mcq', question: 'Cortisol, a major glucocorticoid, plays a key role in:', options: ['Regulating carbohydrate metabolism and the stress response', 'Regulating blood calcium levels exclusively', 'Sperm production', 'Milk secretion'], correctIndex: 0, explanation: 'Cortisol regulates carbohydrate/protein/fat metabolism and helps the body respond to stress.', difficulty: 'medium' },
  { id: 'cc-24', type: 'mcq', question: 'Aldosterone, a major mineralocorticoid, primarily regulates:', options: ['Blood glucose levels', 'Sodium and water balance in the body', 'Milk production', 'Thyroid hormone synthesis'], correctIndex: 1, explanation: 'Aldosterone promotes sodium (and water) reabsorption in the kidney, regulating electrolyte/fluid balance.', difficulty: 'medium' },
  { id: 'cc-25', type: 'mcq', question: 'The adrenal medulla secretes the hormones:', options: ['Insulin and glucagon', 'Adrenaline (epinephrine) and noradrenaline (norepinephrine)', 'Thyroxine and calcitonin', 'Testosterone and oestrogen'], correctIndex: 1, explanation: 'The adrenal medulla secretes the catecholamines adrenaline and noradrenaline.', difficulty: 'medium' },
  { id: 'cc-26', type: 'mcq', question: "Adrenaline and noradrenaline, often called 'fight or flight' hormones, generally cause:", options: ['Decreased heart rate and lowered blood glucose', 'Increased heart rate, elevated blood glucose, and heightened alertness', 'No physiological effect', 'Only digestive stimulation'], correctIndex: 1, explanation: 'These hormones prepare the body for emergency action — raising heart rate and blood glucose, and boosting alertness.', difficulty: 'medium' },
  { id: 'cc-27', type: 'mcq', question: 'The pancreas, besides its digestive function, acts as an endocrine gland through clusters of cells called the:', options: ['Islets of Langerhans', 'Loops of Henle', 'Alveoli', 'Nephrons'], correctIndex: 0, explanation: 'The Islets of Langerhans within the pancreas are the endocrine portion, secreting insulin and glucagon.', difficulty: 'medium' },
  { id: 'cc-28', type: 'mcq', question: 'Insulin, secreted by beta cells of the pancreatic islets, functions mainly to:', options: ['Increase blood glucose levels', 'Decrease blood glucose levels by promoting cellular glucose uptake', 'Increase blood calcium', 'Stimulate milk production'], correctIndex: 1, explanation: 'Insulin lowers blood glucose by promoting its uptake and utilisation/storage by cells.', difficulty: 'medium' },
  { id: 'cc-29', type: 'mcq', question: 'Glucagon, secreted by alpha cells of the pancreatic islets, functions mainly to:', options: ['Decrease blood glucose levels', 'Increase blood glucose levels, largely by promoting glycogen breakdown in the liver', 'Regulate blood calcium', 'Promote water reabsorption in the kidney'], correctIndex: 1, explanation: 'Glucagon raises blood glucose by stimulating glycogenolysis (glycogen breakdown) in the liver.', difficulty: 'medium' },
  { id: 'cc-30', type: 'mcq', question: 'The primary male gonads, the testes, secrete the hormone:', options: ['Oestrogen', 'Testosterone', 'Progesterone', 'Relaxin'], correctIndex: 1, explanation: 'Testosterone, the main male sex hormone, is secreted by the testes (Leydig cells).', difficulty: 'easy' },
  { id: 'cc-31', type: 'mcq', question: 'The primary female gonads, the ovaries, secrete which hormones?', options: ['Testosterone only', 'Oestrogen and progesterone', 'Insulin and glucagon', 'Adrenaline only'], correctIndex: 1, explanation: 'The ovaries secrete oestrogens and progesterone, regulating female reproductive functions.', difficulty: 'easy' },
  { id: 'cc-32', type: 'mcq', question: 'Steroid hormones, being lipid-soluble, typically act on target cells by:', options: ['Binding to cell-surface receptors only, never entering the cell', 'Diffusing across the plasma membrane and binding to intracellular/nuclear receptors', 'Being completely unable to enter any cell', 'Acting only via second messengers, with no receptor binding'], correctIndex: 1, explanation: 'Steroid hormones, being lipophilic, cross the plasma membrane directly and bind intracellular receptors, often affecting gene expression.', difficulty: 'medium' },
  { id: 'cc-33', type: 'mcq', question: 'Peptide/protein hormones, being generally water-soluble, typically act on target cells by:', options: ['Diffusing directly into the cytoplasm and nucleus', 'Binding to cell-surface receptors, often triggering a second messenger cascade inside the cell', 'Never binding to any receptor at all', 'Only acting on the mitochondria directly'], correctIndex: 1, explanation: 'Peptide hormones typically cannot cross the membrane and instead bind surface receptors, activating intracellular signalling cascades.', difficulty: 'medium' },
  { id: 'cc-34', type: 'mcq', question: 'A common "second messenger" molecule activated by many peptide hormone-receptor interactions is:', options: ['Cyclic AMP (cAMP)', 'Glucose', 'Sodium chloride', 'Water'], correctIndex: 0, explanation: 'Cyclic AMP (cAMP) is a widely used second messenger that relays signals from surface receptors within the cell.', difficulty: 'medium' },
  { id: 'cc-35', type: 'mcq', question: 'Hyposecretion of Growth Hormone during childhood can lead to a condition called:', options: ['Gigantism', 'Pituitary dwarfism', 'Acromegaly', 'Goitre'], correctIndex: 1, explanation: 'Insufficient GH during childhood growth years results in pituitary dwarfism.', difficulty: 'medium' },
  { id: 'cc-36', type: 'mcq', question: 'Hypersecretion of Growth Hormone during childhood (before bone growth plates close) can lead to a condition called:', options: ['Pituitary dwarfism', 'Gigantism', 'Hypothyroidism', 'Diabetes mellitus'], correctIndex: 1, explanation: 'Excess GH during the growth years causes excessive height/growth, known as gigantism.', difficulty: 'medium' },
  { id: 'cc-37', type: 'mcq', question: 'Hypersecretion of Growth Hormone in adulthood, after growth plates have closed, leads to a condition called:', options: ['Gigantism', 'Acromegaly (enlargement of extremities/facial features)', 'Cretinism', 'Diabetes insipidus'], correctIndex: 1, explanation: "Since long bones can't lengthen further in adults, excess GH instead causes disproportionate growth of extremities/facial bones — acromegaly.", difficulty: 'medium' },
  { id: 'cc-38', type: 'mcq', question: 'Iodine deficiency, impairing thyroid hormone synthesis, commonly leads to enlargement of the thyroid gland, a condition called:', options: ['Goitre', 'Gigantism', 'Cretinism only', 'Addison\'s disease'], correctIndex: 0, explanation: 'Iodine deficiency causes the thyroid to enlarge (goitre) as it attempts to compensate for insufficient hormone synthesis.', difficulty: 'medium' },
  { id: 'cc-39', type: 'mcq', question: 'Hypothyroidism (deficient thyroid hormone) present from birth/early childhood can cause a condition of impaired physical and mental development called:', options: ['Cretinism', 'Acromegaly', 'Gigantism', 'Grave\'s disease'], correctIndex: 0, explanation: 'Congenital or early childhood hypothyroidism, if untreated, can cause cretinism — stunted growth and impaired mental development.', difficulty: 'medium' },
  { id: 'cc-40', type: 'mcq', question: "Grave's disease, a form of hyperthyroidism, results from:", options: ['Deficient thyroid hormone secretion', 'Excessive thyroid hormone secretion, often due to autoimmune stimulation', 'Complete absence of the thyroid gland', 'Iodine excess with no other cause'], correctIndex: 1, explanation: "Grave's disease is an autoimmune condition causing hyperthyroidism (excess thyroid hormone).", difficulty: 'medium' },
  { id: 'cc-41', type: 'mcq', question: "Addison's disease results from insufficient secretion of hormones from the:", options: ['Thyroid gland', 'Adrenal cortex', 'Pancreas', 'Pituitary gland only'], correctIndex: 1, explanation: "Addison's disease is caused by insufficient adrenal cortex hormone (cortisol/aldosterone) secretion.", difficulty: 'medium' },
  { id: 'cc-42', type: 'mcq', question: "Cushing's syndrome results from:", options: ['Insufficient cortisol secretion', 'Excess cortisol secretion/exposure', 'Excess insulin secretion', 'Insufficient insulin secretion'], correctIndex: 1, explanation: "Cushing's syndrome is caused by excessive cortisol levels, whether from the adrenal cortex or external sources.", difficulty: 'medium' },
  { id: 'cc-43', type: 'mcq', question: 'Diabetes mellitus, characterised by high blood glucose, primarily results from:', options: ['Excess insulin production or action', 'Insufficient insulin production or impaired insulin action (insulin resistance)', 'Excess glucagon deficiency only', 'A disorder of the thyroid gland'], correctIndex: 1, explanation: 'Diabetes mellitus arises from insufficient insulin production/action, leading to chronically elevated blood glucose.', difficulty: 'medium' },
  { id: 'cc-44', type: 'mcq', question: 'Diabetes insipidus, distinct from diabetes mellitus, results from:', options: ['Insufficient insulin secretion', 'Insufficient ADH secretion or action, leading to excessive dilute urine output', 'Excess thyroid hormone', 'Excess cortisol'], correctIndex: 1, explanation: 'Diabetes insipidus stems from ADH deficiency/resistance, causing large volumes of dilute urine.', difficulty: 'medium' },
  { id: 'cc-45', type: 'mcq', question: 'The kidney, besides its excretory role, also acts as an endocrine organ by secreting:', options: ['Insulin', 'Erythropoietin, which stimulates red blood cell production', 'Thyroxine', 'Testosterone'], correctIndex: 1, explanation: 'The kidney secretes erythropoietin, stimulating red blood cell production in bone marrow.', difficulty: 'medium' },
  { id: 'cc-46', type: 'mcq', question: 'The heart, besides its pumping function, also acts as an endocrine organ by secreting:', options: ['Insulin', 'Atrial Natriuretic Factor (ANF)', 'Thyroxine', 'Cortisol'], correctIndex: 1, explanation: 'The heart secretes ANF, which helps regulate blood pressure and sodium/water balance.', difficulty: 'medium' },
  { id: 'cc-47', type: 'mcq', question: 'Which of the following best describes a key functional difference between the nervous system and the endocrine system in coordinating body functions?', options: ['The nervous system acts slower than the endocrine system in all cases', 'The nervous system typically produces rapid, short-lived responses, while the endocrine system often produces slower, longer-lasting effects', 'Both systems work identically with no functional differences', 'The endocrine system uses only electrical signals'], correctIndex: 1, explanation: 'Nerve impulses are fast and brief; hormonal effects, though slower to onset, often persist much longer.', difficulty: 'medium' },
  { id: 'cc-48', type: 'mcq', question: 'A hormone can only act on cells that possess the appropriate:', options: ['Cell wall', 'Specific receptor for that hormone', 'Chloroplasts', 'Ribosomes only'], correctIndex: 1, explanation: 'A hormone affects only target cells expressing the specific receptor it can bind to.', difficulty: 'medium' },
  { id: 'cc-49', type: 'mcq', question: 'Which of the following hormone pairs generally act in a broadly antagonistic (opposing) manner regarding blood glucose regulation?', options: ['Insulin and glucagon', 'Oxytocin and prolactin', 'Melatonin and thymosin', 'Calcitonin and thyroxine'], correctIndex: 0, explanation: 'Insulin lowers and glucagon raises blood glucose — a classic antagonistic hormone pair.', difficulty: 'medium' },
  { id: 'cc-50', type: 'mcq', question: 'Which of the following best summarises the overall significance of the endocrine system?', options: ['It has no real physiological importance', 'It works together with the nervous system to coordinate and regulate diverse body functions via chemical messengers (hormones)', 'It only regulates digestion', 'It functions completely independently, with no interaction with the nervous system'], correctIndex: 1, explanation: 'The endocrine system, via hormones, works alongside the nervous system for integrated, whole-body coordination.', difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'cc-ar-1', type: 'assertion-reason', question: 'Assertion (A): The pituitary gland is called the master gland.\nReason (R): It regulates the secretory activity of several other endocrine glands via its hormones.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This regulatory influence over other glands is exactly why the pituitary earns the "master gland" title.', difficulty: 'medium' },
  { id: 'cc-ar-2', type: 'assertion-reason', question: 'Assertion (A): Oxytocin and ADH are synthesised in the posterior pituitary itself.\nReason (R): Both hormones are actually synthesised in the hypothalamus and merely released/stored in the posterior pituitary.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'These hormones are actually synthesised in the HYPOTHALAMUS, not the posterior pituitary itself (A is false); R correctly describes their real site of synthesis and the posterior pituitary\'s storage/release role.', difficulty: 'medium' },
  { id: 'cc-ar-3', type: 'assertion-reason', question: 'Assertion (A): TSH is secreted by the thyroid gland itself.\nReason (R): TSH is secreted by the anterior pituitary and stimulates the thyroid gland.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'TSH is actually secreted by the ANTERIOR PITUITARY (not the thyroid) (A is false); R correctly describes the real source and function of TSH.', difficulty: 'medium' },
  { id: 'cc-ar-4', type: 'assertion-reason', question: 'Assertion (A): Melatonin, secreted by the pineal gland, helps regulate circadian rhythms.\nReason (R): Melatonin secretion typically varies with the light-dark cycle.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This light-dependent secretion pattern is exactly how melatonin helps regulate circadian (day-night) rhythms.', difficulty: 'medium' },
  { id: 'cc-ar-5', type: 'assertion-reason', question: 'Assertion (A): Thyroid hormone synthesis requires adequate dietary iodine.\nReason (R): Iodine deficiency can lead to goitre, an enlargement of the thyroid gland.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true and related, but R describes a downstream CONSEQUENCE of iodine deficiency rather than directly explaining why iodine itself is needed for synthesis.', difficulty: 'medium' },
  { id: 'cc-ar-6', type: 'assertion-reason', question: 'Assertion (A): Calcitonin and parathyroid hormone (PTH) have similar effects on blood calcium levels.\nReason (R): Calcitonin lowers blood calcium, while PTH raises it — largely opposing actions.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Calcitonin and PTH actually have OPPOSING (not similar) effects (A is false); R correctly describes their real, antagonistic actions.', difficulty: 'medium' },
  { id: 'cc-ar-7', type: 'assertion-reason', question: 'Assertion (A): The thymus gland plays a role in the maturation of T-lymphocytes.\nReason (R): The thymus secretes hormones called thymosins.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Thymosin secretion is precisely the mechanism by which the thymus supports T-lymphocyte maturation.', difficulty: 'medium' },
  { id: 'cc-ar-8', type: 'assertion-reason', question: "Assertion (A): The thymus gland grows progressively larger throughout adulthood and old age.\nReason (R): The thymus typically undergoes involution (shrinkage) with advancing age after childhood.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The thymus actually SHRINKS (not grows) with age (A is false); R correctly describes this age-related involution.', difficulty: 'medium' },
  { id: 'cc-ar-9', type: 'assertion-reason', question: 'Assertion (A): Cortisol helps the body respond to stress.\nReason (R): Cortisol influences carbohydrate, protein, and fat metabolism to help meet increased energy demands.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "These metabolic effects are exactly why cortisol is central to the body's stress response.", difficulty: 'medium' },
  { id: 'cc-ar-10', type: 'assertion-reason', question: 'Assertion (A): Aldosterone decreases sodium reabsorption in the kidney.\nReason (R): Aldosterone acts on the kidney tubules to promote sodium (and water) reabsorption, raising blood volume/pressure.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Aldosterone actually INCREASES (not decreases) sodium reabsorption (A is false); R correctly describes its real, sodium-retaining action.', difficulty: 'medium' },
  { id: 'cc-ar-11', type: 'assertion-reason', question: "Assertion (A): Adrenaline and noradrenaline are called 'fight or flight' hormones.\nReason (R): They increase heart rate, elevate blood glucose, and heighten alertness in stressful situations.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'These specific physiological effects are exactly why these hormones earn the fight-or-flight designation.', difficulty: 'medium' },
  { id: 'cc-ar-12', type: 'assertion-reason', question: 'Assertion (A): Insulin is secreted by alpha cells of the pancreatic islets.\nReason (R): Insulin lowers blood glucose levels by promoting cellular glucose uptake.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Insulin is actually secreted by BETA cells (not alpha cells) (A is false); R correctly describes insulin\'s real glucose-lowering function.', difficulty: 'medium' },
  { id: 'cc-ar-13', type: 'assertion-reason', question: 'Assertion (A): Glucagon and insulin act antagonistically on blood glucose regulation.\nReason (R): Insulin lowers blood glucose, while glucagon raises it, largely via effects on liver glycogen.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'These opposing glucose-regulating effects are exactly what make insulin and glucagon antagonistic hormones.', difficulty: 'medium' },
  { id: 'cc-ar-14', type: 'assertion-reason', question: 'Assertion (A): Steroid hormones typically bind to receptors on the cell surface, never entering the cell.\nReason (R): Steroid hormones are lipid-soluble and can diffuse directly across the plasma membrane.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Steroid hormones actually DO enter the cell and bind intracellular/nuclear receptors (A is false), precisely because they are lipid-soluble and can cross the membrane, as R correctly states.', difficulty: 'medium' },
  { id: 'cc-ar-15', type: 'assertion-reason', question: 'Assertion (A): Peptide hormones generally use second messengers like cAMP to relay their signal inside the cell.\nReason (R): Peptide hormones typically bind cell-surface receptors, since they cannot easily cross the lipid plasma membrane.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This inability to cross the membrane directly is exactly why peptide hormones rely on surface receptors and second messengers.', difficulty: 'medium' },
  { id: 'cc-ar-16', type: 'assertion-reason', question: 'Assertion (A): Excess Growth Hormone in childhood causes pituitary dwarfism.\nReason (R): Pituitary dwarfism results from GH deficiency, not excess, during the growth years.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Excess GH in childhood actually causes GIGANTISM (not dwarfism) (A is false); R correctly identifies the true cause of pituitary dwarfism (GH deficiency).', difficulty: 'medium' },
  { id: 'cc-ar-17', type: 'assertion-reason', question: "Assertion (A): Acromegaly results from excess Growth Hormone in adulthood, after bone growth plates have closed.\nReason (R): Since long bones cannot lengthen further, excess GH instead causes disproportionate growth of extremities and facial features.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "This shift to extremity/facial growth (since long bones can't lengthen) is exactly why adult-onset excess GH causes acromegaly rather than increased height.", difficulty: 'medium' },
  { id: 'cc-ar-18', type: 'assertion-reason', question: "Assertion (A): Addison's disease results from excess adrenal cortex hormone secretion.\nReason (R): Cushing's syndrome results from excess cortisol, a distinct condition from Addison's disease.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "Addison's disease actually results from INSUFFICIENT (not excess) adrenal cortex hormone secretion (A is false); R correctly distinguishes it from Cushing's syndrome, which does involve excess cortisol.", difficulty: 'medium' },
  { id: 'cc-ar-19', type: 'assertion-reason', question: 'Assertion (A): Diabetes insipidus and diabetes mellitus have the same underlying hormonal cause.\nReason (R): Diabetes insipidus results from ADH deficiency/resistance, while diabetes mellitus results from insulin deficiency/resistance.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'These two conditions actually have DIFFERENT hormonal causes, not the same one (A is false); R correctly distinguishes their separate mechanisms.', difficulty: 'medium' },
  { id: 'cc-ar-20', type: 'assertion-reason', question: 'Assertion (A): The kidney and heart, despite not being classified as classical endocrine glands, can also secrete hormones.\nReason (R): The kidney secretes erythropoietin, and the heart secretes Atrial Natriuretic Factor (ANF).', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'These specific hormone-secreting roles are exactly what demonstrate the kidney and heart\'s additional endocrine functions.', difficulty: 'medium' },

  // ---- Statement-based ----
  { id: 'cc-st-1', type: 'statement', question: 'Statement I: Endocrine glands secrete hormones directly into the blood.\nStatement II: Endocrine glands possess ducts to carry their secretions.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — endocrine glands are ductless, releasing hormones directly into blood.', difficulty: 'easy' },
  { id: 'cc-st-2', type: 'statement', question: 'Statement I: GH, TSH, and ACTH are secreted by the anterior pituitary.\nStatement II: Oxytocin and ADH are secreted by the posterior pituitary.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the hormones secreted by each pituitary lobe.', difficulty: 'medium' },
  { id: 'cc-st-3', type: 'statement', question: 'Statement I: Melatonin is secreted by the pineal gland.\nStatement II: Melatonin plays a role in regulating circadian rhythms.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe melatonin and its source.', difficulty: 'easy' },
  { id: 'cc-st-4', type: 'statement', question: 'Statement I: Thyroid hormone synthesis requires calcium.\nStatement II: Thyroid hormone synthesis requires iodine.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — it is iodine, not calcium, that is essential for thyroid hormone synthesis; Statement II correctly identifies iodine.', difficulty: 'medium' },
  { id: 'cc-st-5', type: 'statement', question: 'Statement I: Calcitonin raises blood calcium levels.\nStatement II: Parathyroid hormone raises blood calcium levels.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — calcitonin actually LOWERS blood calcium; Statement II correctly describes PTH\'s calcium-raising effect.', difficulty: 'medium' },
  { id: 'cc-st-6', type: 'statement', question: 'Statement I: The thymus secretes thymosins, important for T-lymphocyte maturation.\nStatement II: The thymus grows larger with advancing age.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the thymus actually shrinks (involutes) with age.', difficulty: 'medium' },
  { id: 'cc-st-7', type: 'statement', question: 'Statement I: The adrenal cortex secretes glucocorticoids, mineralocorticoids, and androgens.\nStatement II: The adrenal medulla secretes adrenaline and noradrenaline.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the hormone classes secreted by the two adrenal regions.', difficulty: 'medium' },
  { id: 'cc-st-8', type: 'statement', question: 'Statement I: Cortisol is a glucocorticoid involved in the stress response.\nStatement II: Aldosterone is a mineralocorticoid involved in sodium/water balance.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these two adrenal cortex hormones and their roles.', difficulty: 'medium' },
  { id: 'cc-st-9', type: 'statement', question: 'Statement I: Insulin is secreted by beta cells of the pancreatic islets.\nStatement II: Glucagon is secreted by alpha cells of the pancreatic islets.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly identify the cell types secreting insulin and glucagon.', difficulty: 'medium' },
  { id: 'cc-st-10', type: 'statement', question: 'Statement I: Insulin increases blood glucose levels.\nStatement II: Glucagon increases blood glucose levels.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — insulin actually DECREASES (not increases) blood glucose; Statement II correctly describes glucagon\'s glucose-raising effect.', difficulty: 'medium' },
  { id: 'cc-st-11', type: 'statement', question: 'Statement I: The testes secrete testosterone.\nStatement II: The ovaries secrete oestrogen and progesterone.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the hormones secreted by the male and female gonads.', difficulty: 'easy' },
  { id: 'cc-st-12', type: 'statement', question: 'Statement I: Steroid hormones act by binding to intracellular/nuclear receptors.\nStatement II: Peptide hormones act mainly by binding cell-surface receptors and using second messengers.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the general mechanisms of steroid and peptide hormone action.', difficulty: 'medium' },
  { id: 'cc-st-13', type: 'statement', question: 'Statement I: Pituitary dwarfism results from excess GH in childhood.\nStatement II: Gigantism results from excess GH in childhood.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — pituitary dwarfism results from GH DEFICIENCY (not excess); Statement II correctly describes gigantism\'s cause.', difficulty: 'medium' },
  { id: 'cc-st-14', type: 'statement', question: 'Statement I: Acromegaly results from excess GH in adulthood.\nStatement II: Acromegaly causes disproportionate growth of extremities and facial features.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the cause and characteristic features of acromegaly.', difficulty: 'medium' },
  { id: 'cc-st-15', type: 'statement', question: 'Statement I: Iodine deficiency can cause goitre.\nStatement II: Congenital hypothyroidism can cause cretinism.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe consequences of thyroid hormone deficiency/dysfunction.', difficulty: 'medium' },
  { id: 'cc-st-16', type: 'statement', question: "Statement I: Grave's disease is a form of hypothyroidism.\nStatement II: Grave's disease is an autoimmune condition causing hyperthyroidism.", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: "Statement I is incorrect — Grave's disease is a form of HYPERthyroidism, not hypothyroidism; Statement II correctly describes it.", difficulty: 'medium' },
  { id: 'cc-st-17', type: 'statement', question: "Statement I: Addison's disease results from adrenal cortex hormone deficiency.\nStatement II: Cushing's syndrome results from excess cortisol.", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: "Both statements correctly describe these two contrasting adrenal cortex disorders.", difficulty: 'medium' },
  { id: 'cc-st-18', type: 'statement', question: 'Statement I: Diabetes mellitus is caused by insulin deficiency or resistance.\nStatement II: Diabetes insipidus is caused by ADH deficiency or resistance.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly distinguish the hormonal causes of these two distinct diabetes conditions.', difficulty: 'medium' },
  { id: 'cc-st-19', type: 'statement', question: 'Statement I: The kidney secretes erythropoietin, an endocrine function.\nStatement II: The heart secretes ANF, an endocrine function.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these additional endocrine roles of the kidney and heart.', difficulty: 'medium' },
  { id: 'cc-st-20', type: 'statement', question: 'Statement I: Nervous system responses are generally faster but shorter-lived than hormonal responses.\nStatement II: Hormonal responses are generally slower to begin but often longer-lasting.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly capture the general timing contrast between neural and hormonal signalling.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'cc-hm-1', type: 'statement', question: 'How many of the following hormones are secreted by the anterior pituitary?\nGrowth Hormone, TSH, ACTH, Oxytocin', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'GH, TSH, and ACTH are anterior pituitary hormones; oxytocin is released from the posterior pituitary.', difficulty: 'medium' },
  { id: 'cc-hm-2', type: 'statement', question: 'How many of the following hormones are released from the posterior pituitary?\nOxytocin, ADH, Prolactin, LH', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Oxytocin and ADH are released from the posterior pituitary; prolactin and LH are secreted by the anterior pituitary.', difficulty: 'medium' },
  { id: 'cc-hm-3', type: 'statement', question: 'How many of the following are hormones secreted by the adrenal cortex?\nCortisol, Aldosterone, Androgens, Adrenaline', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cortisol, aldosterone, and androgens are adrenal cortex hormones; adrenaline is secreted by the adrenal medulla.', difficulty: 'medium' },
  { id: 'cc-hm-4', type: 'statement', question: 'How many of the following are true regarding thyroid hormones?\nThey require iodine for synthesis, They regulate basal metabolic rate, Deficiency can cause goitre, They are secreted by the parathyroid gland', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; thyroid hormones are secreted by the THYROID (not parathyroid) gland.', difficulty: 'medium' },
  { id: 'cc-hm-5', type: 'statement', question: 'How many of the following hormone pairs act antagonistically on their target function?\nInsulin and glucagon (blood glucose), Calcitonin and PTH (blood calcium), Aldosterone and ANF (sodium/water balance), Adrenaline and noradrenaline (heart rate)', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 2, explanation: 'The first three pairs act antagonistically; adrenaline and noradrenaline generally work together (synergistically), not against each other.', difficulty: 'hard' },
  { id: 'cc-hm-6', type: 'statement', question: 'How many of the following are endocrine disorders related to Growth Hormone imbalance?\nPituitary dwarfism, Gigantism, Acromegaly, Goitre', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Pituitary dwarfism, gigantism, and acromegaly are all GH-related disorders; goitre is related to thyroid hormone/iodine deficiency, not GH.', difficulty: 'medium' },
  { id: 'cc-hm-7', type: 'statement', question: 'How many of the following are endocrine disorders related to the adrenal cortex?\nAddison\'s disease, Cushing\'s syndrome, Diabetes mellitus, Diabetes insipidus', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: "Addison's disease and Cushing's syndrome are adrenal cortex disorders; diabetes mellitus relates to insulin, and diabetes insipidus relates to ADH.", difficulty: 'medium' },
  { id: 'cc-hm-8', type: 'statement', question: 'How many of the following organs/glands have a confirmed endocrine function, secreting at least one hormone?\nKidney, Heart, Pancreas, Thymus', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four organs have recognised endocrine functions (erythropoietin, ANF, insulin/glucagon, and thymosins respectively).', difficulty: 'medium' },
  { id: 'cc-hm-9', type: 'statement', question: 'How many of the following are true regarding steroid hormone action?\nThey are lipid-soluble, They diffuse across the plasma membrane, They typically bind intracellular/nuclear receptors, They always require a second messenger like cAMP', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; steroid hormones generally do NOT rely on second messengers like cAMP — that mechanism is typical of peptide hormones instead.', difficulty: 'hard' },
  { id: 'cc-hm-10', type: 'statement', question: 'How many of the following are hormones secreted by the pancreatic islets?\nInsulin, Glucagon, Somatostatin, Thyroxine', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Insulin, glucagon, and somatostatin are all pancreatic islet hormones; thyroxine is secreted by the thyroid gland, unrelated to the pancreas.', difficulty: 'medium' },
];